    END LOOP;
    CLOSE cur;
  END IF;

  IF flag = 1 THEN
    DELETE FROM "Restaurant_Type" WHERE "ResTypeID" < para_ResTypeID;
    IF NULLIF(para_Sex, '') = 'M' THEN
      UPDATE "Restaurant" SET "Rating" = "Rating" - 1 WHERE "Rating" < para_Rating;
    END IF;
  ELSIF flag = 2 AND temp_num > 100 THEN
    UPDATE "Restaurant" SET "Rating" = "Rating" - 10 WHERE "Rating" > 200;
  ELSIF flag = 3 AND temp_text = 'OVER_LIMIT' THEN
    DELETE FROM "Restaurant" WHERE "Rating" > 150;
  ELSIF flag = 4 AND temp_num > 5 THEN
    UPDATE "Student" SET "Sex" = 'PROCESSED' WHERE "Major" < para_Major AND "Sex" = NULLIF(para_Sex, '');
  ELSE
    UPDATE "Restaurant_Type" SET "ResTypeName" = 'DEFAULT' WHERE "ResTypeID" IS NULL;
  END IF;
END;
